unfold maxOfThree maxOfThree_postcond
have h_main : (maxOfThree a b c h_precond) ≥ a ∧ (maxOfThree a b c h_precond) ≥ b ∧ (maxOfThree a b c h_precond) ≥ c ∧ ((maxOfThree a b c h_precond) = a ∨ (maxOfThree a b c h_precond) = b ∨ (maxOfThree a b c h_precond) = c) := by
  dsimp only [maxOfThree, maxOfThree_postcond]
  split_ifs <;>
  (try {
    simp_all [maxOfThree_precond, Int.le_of_lt]
    <;>
    (try omega) <;>
    (try aesop) <;>
    (try
      {
        (try aesop)
        <;>
        (try omega)
        <;>
        (try
          {
            left
            <;> omega
          })
        <;>
        (try
          {
            right
            <;> left
            <;> omega
          })
        <;>
        (try
          {
            right
            <;> right
            <;> omega
          })
      })
  }) <;>
  (try
    {
      constructor <;>
      (try omega) <;>
      (try aesop)
    }) <;>
  (try
    {
      constructor <;>
      (try omega) <;>
      (try aesop)
    }) <;>
  (try
    {
      constructor <;>
      (try omega) <;>
      (try aesop)
    }) <;>
  (try
    {
      aesop
    }) <;>
  (try
    {
      constructor <;>
      (try omega) <;>
      (try aesop)
    }) <;>
  (try
    {
      simp_all [or_iff_not_imp_left, or_iff_not_imp_left]
      <;>
      tauto
    }) <;>
  (try
    {
      omega
    })
-- The above steps use `aesop` to automatically handle the `omega` and other logical steps.
tauto

have h_main : maxOfThree_postcond (a) (b) (c) (maxOfThree (a) (b) (c) h_precond) h_precond := by
  simp only [maxOfThree_postcond, maxOfThree_precond, maxOfThree, maxOfThree_precond] at *
  split_ifs <;> simp_all [le_refl, le_of_lt]
  <;> norm_num <;>
  (try omega) <;>
  (try
    {
      by_cases h : a ≥ b <;> by_cases h' : a ≥ c <;> by_cases h'' : b ≥ c <;>
        by_cases h''' : b ≥ a <;> by_cases h'''' : c ≥ a <;> by_cases h''''' : c ≥ b <;>
          simp_all [max_eq_left, max_eq_right, le_refl, le_of_lt] <;>
          (try omega) <;>
          (try { aesop }) <;>
          (try {
            cases' le_total a b with hab hab <;> cases' le_total b c with hbc hbc <;> cases' le_total c a with hac hac <;>
              simp_all [max_eq_left, max_eq_right, le_refl, le_of_lt] <;>
              (try omega) <;>
              (try { aesop })
          })
    }) <;>
  (try {
    omega
  }) <;>
  (try {
    aesop
  }) <;>
  (try {
    norm_num
    <;> omega
  }) <;>
  (try {
    norm_num
    <;> omega
  }) <;>
  (try {
    omega
  })
  <;>
  (try {
    aesop
  })
  <;>
  (try {
    norm_num
    <;> omega
  })
  <;>
  (try {
    omega
  })
exact h_main

unfold maxOfThree maxOfThree_postcond
have h_main : (maxOfThree (a) (b) (c) h_precond >= a ∧ maxOfThree (a) (b) (c) h_precond >= b ∧ maxOfThree (a) (b) (c) h_precond >= c) ∧ (maxOfThree (a) (b) (c) h_precond = a ∨ maxOfThree (a) (b) (c) h_precond = b ∨ maxOfThree (a) (b) (c) h_precond = c) := by
  dsimp only [maxOfThree, maxOfThree_precond, maxOfThree_postcond] at h_precond ⊢
  split_ifs at * <;>
  (try { contradiction }) <;>
  (try { simp_all }) <;>
  (try { omega }) <;>
  (try {
    aesop
  }) <;>
  (try {
    by_cases h : a ≥ b <;> by_cases h' : a ≥ c <;> by_cases h'' : b ≥ a <;> by_cases h''' : b ≥ c <;> simp_all [Int.le_of_lt, Int.le_of_lt] <;> omega
  }) <;>
  (try {
    by_cases h : a ≥ b <;> by_cases h' : a ≥ c <;> by_cases h'' : b ≥ a <;> by_cases h''' : b ≥ c <;> simp_all [Int.le_of_lt, Int.le_of_lt] <;> omega
  })
  <;>
  (try {
    by_cases h : a ≥ b <;> by_cases h' : a ≥ c <;> by_cases h'' : b ≥ a <;> by_cases h''' : b ≥ c <;> simp_all [Int.le_of_lt, Int.le_of_lt] <;> omega
  })
  <;>
  (try {
    by_cases h : a ≥ b <;> by_cases h' : a ≥ c <;> by_cases h'' : b ≥ a <;> by_cases h''' : b ≥ c <;> simp_all [Int.le_of_lt, Int.le_of_lt] <;> omega
  })

exact h_main

unfold hasOppositeSign hasOppositeSign_postcond
have h_main : hasOppositeSign_postcond (a) (b) (hasOppositeSign (a) (b) h_precond) h_precond := by
  dsimp only [hasOppositeSign, hasOppositeSign_postcond, hasOppositeSign_precond] at *
  <;>
  (try constructor) <;>
  (try simp_all) <;>
  (try
    {
      by_cases h₁ : a < 0 <;> by_cases h₂ : b < 0 <;> by_cases h₃ : a > 0 <;> by_cases h₄ : b > 0 <;>
        simp_all [mul_comm, mul_assoc, mul_left_comm, Int.mul_emod, Int.add_emod, Int.sub_emod]
      <;>
        (try omega) <;>
        (try
          {
            nlinarith
          }) <;>
        (try
          {
            aesop
          })
    }) <;>
  (try
    {
      by_cases h₁ : a < 0 <;> by_cases h₂ : b < 0 <;> by_cases h₃ : a > 0 <;> by_cases h₄ : b > 0 <;>
        simp_all [mul_comm, mul_assoc, mul_left_comm, Int.mul_emod, Int.add_emod, Int.sub_emod]
      <;>
        (try omega) <;>
        (try
          {
            nlinarith
          }) <;>
        (try
          {
            aesop
          })
    }) <;>
  (try
    {
      aesop
    }) <;>
  (try
    {
      omega
    })
exact h_main

have h_main : Triple_postcond (x) (Triple (x) h_precond) h_precond := by
  simp only [Triple_precond, Triple, Triple_postcond]
  split_ifs <;>
  (try { contradiction }) <;>
  (try { simp_all [Int.mul_ediv_cancel_left, Int.mul_emod, Int.add_emod, Int.emod_emod] }) <;>
  (try {
    ring_nf at * <;>
    norm_num at * <;>
    omega
  }) <;>
  (try {
    cases x <;> simp_all [Int.mul_ediv_cancel_left, Int.mul_emod, Int.add_emod, Int.emod_emod] <;>
    ring_nf at * <;>
    norm_num at * <;>
    omega
  }) <;>
  (try {
    aesop
  }) <;>
  (try {
    omega
  })
  <;>
  (try {
    simp_all [Int.mul_ediv_cancel_left, Int.mul_emod, Int.add_emod, Int.emod_emod]
    <;> ring_nf at * <;> norm_num at * <;> omega
  })
  <;>
  (try {
    aesop
  })
  <;>
  (try {
    omega
  })
exact h_main

unfold lastDigit lastDigit_postcond
have h₁ : lastDigit_postcond (n) (lastDigit (n) h_precond) h_precond := by
  simp [lastDigit, lastDigit_postcond, lastDigit_precond, Nat.mod_eq_of_lt]
  <;>
  (try omega) <;>
  (try
    {
      constructor <;>
      (try omega) <;>
      (try
        {
          simp [Nat.mod_eq_of_lt]
          <;> omega
        })
    }) <;>
  (try
    {
      constructor <;>
      omega
    }) <;>
  (try
    {
      simp [Nat.mod_eq_of_lt]
      <;> omega
    })
  <;>
  (try
    {
      omega
    })
exact h₁

have h_main : replaceChars_postcond (s) (oldChar) (newChar) (replaceChars (s) (oldChar) (newChar) h_precond) h_precond := by
  dsimp [replaceChars, replaceChars_postcond]
  <;>
  (try simp_all) <;>
  (try
    {
      simp_all [List.length_map, List.length_toList]
    }) <;>
  (try
    {
      constructor <;>
      intro i _ <;>
      (try cases i <;> simp_all [List.get, List.get?, List.nthLe, List.map]) <;>
      (try
        {
          split_ifs <;>
          simp_all [List.get, List.get?, List.nthLe, List.map] <;>
          (try omega) <;>
          (try
            {
              cases s with
              | mk l =>
                cases l with
                | nil => simp_all
                | cons hd tl =>
                  simp_all [List.get]
                  <;>
                  (try aesop)
              }
            )
        }
      )
    }
  ) <;>
  aesop
exact h_main

have h_main : toUppercase_postcond (s) (toUppercase (s) h_precond) h_precond := by
  dsimp [toUppercase, toUppercase_postcond, isLowerCase, shiftMinus32]
  constructor
  · -- Prove that the lengths are the same
    simp [List.length_map]
  · -- Prove the condition for each index i
    intro i h₁
    have h₂ : i < s.length := h₁
    -- We need to consider the i-th character of the list
    simp [List.get]
    <;>
    (try
      {
        split <;> simp_all [List.get] <;>
        (try omega) <;>
        (try
          {
            simp_all [List.get]
            <;>
            (try
              {
                simp_all [List.get]
                <;>
                (try
                  {
                    omega
                  })
              })
          })
      })
    <;>
    (try
      {
        -- If the character is lowercase, the mapping works
        simp_all [List.get]
        <;>
        (try
          {
            simp_all [List.get]
            <;>
            (try
              {
                omega
              })
          })
      })
    <;>
    (try
      {
        -- If the character is not lowercase, the mapping works
        simp_all [List.get]
        <;>
        (try
          {
            simp_all [List.get]
            <;>
            (try
              {
                omega
              })
          })
      })
    <;>
    (try
      {
        -- If the character is lowercase, show that the shift is correct
        split_ifs <;> simp_all [List.get, Char.ofNat_le] <;>
        (try
          {
            norm_num at *
            <;>
            omega
          })
        <;>
        (try
          {
            simp_all [List.get]
            <;>
            omega
          })
      })
    <;>
    (try
      {
        -- If the character is not lowercase, the mapping works
        split_ifs <;> simp_all [List.get, Char.ofNat_le] <;>
        (try omega) <;> (try omega) <;>
        (try
          {
            simp_all [List.get]
            <;>
            omega
          })
      })
exact h_main

unfold toUppercase toUppercase_postcond
have h_main : toUppercase_postcond (s) (toUppercase (s) h_precond) h_precond := by
  unfold toUppercase toUppercase_postcond
  dsimp only [List.length, List.map, List.map_append, List.map_nil, List.append]
  <;>
  (try simp_all) <;>
  (try aesop) <;>
  (try
    {
      ext i
      by_cases h : isLowerCase (s[i]!)
      <;> simp_all [isLowerCase, shiftMinus32, Char.ofNat]
      <;> omega
    }) <;>
  (try
    {
      cases s <;> simp_all [String.toList, List.map, List.map, List.length, List.append, List.nil]
      <;> aesop
    }) <;>
  (try
    {
      cases i <;> simp_all [String.toList, List.map, List.map, List.length, List.append, List.nil]
      <;> aesop
    }) <;>
  (try
    {
      omega
    }) <;>
  (try
    {
      aesop
    })
exact h_main

unfold Abs Abs_postcond
have h_main : Abs_postcond x (Abs (x) h_precond) h_precond := by
  simp [Abs_precond, Abs, abs_of_nonneg, abs_of_nonpos, Int.ofNat_eq_coe]
  <;>
  (try
    {
      split_ifs <;> simp_all (config := {decide := true})
      <;>
      (try omega) <;>
      (try
        {
          cases' le_or_lt 0 x with hx hx <;> simp_all [abs_of_nonneg, abs_of_neg] <;> omega
        })
    }) <;>
  (try
    {
      constructor <;> intro h <;>
      (try omega) <;>
      (try
        {
          cases' le_or_lt 0 x with hx hx <;> simp_all [abs_of_nonneg, abs_of_neg] <;> omega
        }) <;>
      (try
        {
          omega
        })
    }) <;>
  (try
    {
      cases' le_or_lt 0 x with hx hx <;> simp_all [abs_of_nonneg, abs_of_neg] <;> omega
    }) <;>
  (try
    {
      omega
    })
  <;>
  (try
    {
      aesop
    })
  <;>
  (try
    {
      linarith
    })
  <;>
  (try
    {
      omega
    })
exact h_main

have h₁ : ((minOfThree (a) (b) (c) h_precond : Int) ≤ a ∧ (minOfThree (a) (b) (c) h_precond : Int) ≤ b ∧ (minOfThree (a) (b) (c) h_precond : Int) ≤ c) ∧ ((minOfThree (a) (b) (c) h_precond : Int) = a ∨ (minOfThree (a) (b) (c) h_precond : Int) = b ∨ (minOfThree (a) (b) (c) h_precond : Int) = c) := by
  dsimp only [minOfThree, minOfThree_postcond, minOfThree_precond]
  -- Consider the cases based on the comparisons between a, b, and c
  split_ifs with h₁ h₂ h₃ <;> simp_all [and_imp, Prod.exists, exists_and_right, exists_prop]
  <;>
  (try {
    aesop
  }) <;>
  (try {
    omega
  }) <;>
  (try {
    exact ⟨by omega, by omega, by omega⟩
  }) <;>
  (try {
    exact Or.inl (by omega)
  }) <;>
  (try {
    exact Or.inr (Or.inl (by omega))
  }) <;>
  (try {
    exact Or.inr (Or.inr (by omega))
  })
  <;>
  (try {
    aesop
  })
  <;>
  (try {
    omega
  })
  <;>
  (try {
    exact ⟨by omega, by omega, by omega⟩
  })
  <;>
  (try {
    exact Or.inl (by omega)
  })
  <;>
  (try {
    exact Or.inr (Or.inl (by omega))
  })
  <;>
  (try {
    exact Or.inr (Or.inr (by omega))
  })

exact h₁

unfold minOfThree minOfThree_postcond
have h_main : (minOfThree a b c h_precond) ≤ a ∧ (minOfThree a b c h_precond) ≤ b ∧ (minOfThree a b c h_precond) ≤ c ∧ ((minOfThree a b c h_precond) = a ∨ (minOfThree a b c h_precond) = b ∨ (minOfThree a b c h_precond) = c) := by
  dsimp only [minOfThree_postcond, minOfThree, minOfThree_precond] at *
  split_ifs with h₁ h₂ h₃ <;> simp_all [minOfThree_postcond, minOfThree, minOfThree_precond]
  <;> (try omega) <;> (try {
    aesop
  }) <;> (try {
    norm_num at * <;>
    omega
  }) <;> (try {
    aesop
  }) <;> (try {
    norm_num at * <;>
    omega
  }) <;> (try {
    aesop
  })
  <;> (try {
    norm_num at * <;>
    omega
  })
  <;> omega
  <;> aesop
  <;> aesop
  <;> aesop

simp_all [minOfThree_postcond]
<;> aesop

have h_main : minOfThree_postcond (a) (b) (c) (minOfThree (a) (b) (c) h_precond) h_precond := by
  dsimp only [minOfThree, minOfThree_precond, minOfThree_postcond] at *
  split_ifs at * <;>
  (try { contradiction }) <;>
  (try {
    simp_all [Int.le_of_lt]
    <;>
    (try { omega }) <;>
    (try {
      norm_num at *
      <;>
      (try { omega }) <;>
      (try {
        aesop
      })
    })
  }) <;>
  (try {
    aesop
  }) <;>
  (try {
    omega
  }) <;>
  (try {
    norm_num at *
    <;>
    aesop
  }) <;>
  (try {
    omega
  }) <;>
  (try {
    aesop
  })
  <;>
  (try {
    omega
  })
  <;>
  (try {
    aesop
  })
exact h_main

unfold minOfThree minOfThree_postcond
have h_main : minOfThree_postcond (a) (b) (c) (minOfThree (a) (b) (c) h_precond) h_precond := by
  dsimp [minOfThree, minOfThree_postcond, minOfThree_precond] at *
  split_ifs at * <;>
  (try { contradiction }) <;>
  (try { aesop }) <;>
  (try {
    constructor <;>
    (try { constructor <;> omega }) <;>
    (try { simp_all [Int.le_of_lt] <;> omega }) <;>
    (try { aesop })
  }) <;>
  (try {
    aesop
  }) <;>
  (try {
    omega
  }) <;>
  (try {
    aesop
  }) <;>
  (try {
    simp_all [Int.le_of_lt] <;> omega
  })
  <;>
  aesop
exact h_main

have h_main : (myMin a b h_precond ≤ a ∧ myMin a b h_precond ≤ b) ∧ (myMin a b h_precond = a ∨ myMin a b h_precond = b) := by
  dsimp [myMin, myMin_precond] at *
  split_ifs <;> simp_all [Int.le_refl, Int.le_of_lt] <;>
  (try { omega }) <;>
  (try {
    exact Or.inl (by linarith) }) <;>
  (try {
    exact Or.inr (by linarith) }) <;>
  (try {
    exact ⟨by linarith, by linarith⟩ })
  <;>
  (try
    {
      exact Or.inl (by linarith)
    })
  <;>
  (try
    {
      exact Or.inr (by linarith)
    })
  <;>
  (try
    {
      exact ⟨by linarith, by linarith⟩
    })
exact h_main

unfold Swap Swap_postcond
have h_main : Swap_postcond (X) (Y) (Swap (X) (Y) h_precond) h_precond := by
  dsimp [Swap, Swap_postcond] at *
  <;>
  (try aesop) <;>
  (try
    {
      by_cases h : X = Y <;> simp_all [Prod.fst, Prod.snd] <;>
      (try omega) <;>
      (try aesop)
    }) <;>
  (try
    {
      simp_all [Prod.fst, Prod.snd] <;>
      aesop
    }) <;>
  (try
    {
      by_cases h : X = Y <;> simp_all [Prod.fst, Prod.snd] <;>
      (try omega) <;>
      (try aesop)
    }) <;>
  (try
    {
      aesop
    }) <;>
  (try
    {
      simp_all [Prod.fst, Prod.snd] <;>
      aesop
    }) <;>
  (try
    {
      aesop
    })
  <;>
  (try
    {
      simp_all [Prod.fst, Prod.snd] <;>
      aesop
    })
exact h_main

unfold SwapArithmetic SwapArithmetic_postcond
have h_main : SwapArithmetic (X) (Y) h_precond = (Y, X) := by
  simp [SwapArithmetic, Prod.ext_iff]
  <;>
  (try omega) <;>
  (try
    {
      cases' h_precond with h₁ h₂ <;>
      simp_all [SwapArithmetic_precond] <;>
      omega
    }) <;>
  (try
    {
      aesop
    })
  <;>
  (try
    {
      ring_nf
      <;>
      omega
    })
  <;>
  (try
    {
      aesop
    })
  <;>
  (try
    {
      omega
    })

have h_final : SwapArithmetic_postcond (X) (Y) (SwapArithmetic (X) (Y) h_precond) h_precond := by
  rw [h_main]
  simp [SwapArithmetic_postcond]
  <;>
  (try omega) <;>
  (try
    {
      cases' h_precond with h₁ h₂ <;>
      simp_all [SwapArithmetic_precond] <;>
      aesop
    }) <;>
  (try
    {
      aesop
    })
  <;>
  (try
    {
      omega
    })
  <;>
  (try
    {
      aesop
    })
  <;>
  (try
    {
      aesop
    })
  <;>
  (try
    {
      aesop
    })

apply h_final

unfold SwapSimultaneous SwapSimultaneous_postcond
have h_main : SwapSimultaneous_postcond (X) (Y) (SwapSimultaneous (X) (Y) h_precond) h_precond := by
  dsimp [SwapSimultaneous, SwapSimultaneous_postcond] at *
  <;> constructor <;>
  (try simp_all) <;>
  (try {
    intro h
    simp_all [ne_eq, Prod.ext_iff]
    <;>
    (try omega) <;>
    (try {
      cases h
      <;> simp_all [ne_eq, not_false_iff]
      <;> omega
    })
  }) <;>
  (try {
    aesop
  }) <;>
  (try {
    cases h_precond <;> simp_all
  })
  <;>
  (try {
    aesop
  })
  <;>
  (try {
    omega
  })
  <;>
  (try {
    simp_all [ne_eq, Prod.ext_iff]
    <;>
    aesop
  })
  <;>
  (try {
    aesop
  })
exact h_main

have h_main : SwapSimultaneous_postcond (X) (Y) (SwapSimultaneous (X) (Y) h_precond) h_precond := by
  dsimp [SwapSimultaneous_postcond, SwapSimultaneous] at *
  <;>
  (try tauto) <;>
  (try
    {
      by_cases h : X = Y <;>
      by_cases h₁ : X = Y <;>
      by_cases h₂ : X = Y <;>
      simp_all [Prod.ext_iff] <;>
      (try omega) <;>
